(()=>{const $=id=>document.getElementById(id);let page='dashboard',customer='C1',role='LIM';const customers=[{id:'C1',name:'ABC TRADING PTE. LTD.',country:'SINGAPORE',currency:'USD',term:'30% + 70%',due:'USD 5,000.00',staff:'LIM'},{id:'C2',name:'HORIZON DISTRIBUTION SDN. BHD.',country:'MALAYSIA',currency:'MYR',term:'14 days',due:'MYR 0.00',staff:'LIM'},{id:'C3',name:'EASTERN WHOLESALE LTD.',country:'UNITED KINGDOM',currency:'GBP',term:'Cash',due:'GBP 2,450.00',staff:'TAN'}];const table=(heads,body,cls='')=>'<section class="panel '+cls+'"><div class="scroll"><table><thead><tr>'+heads.map((h,i)=>'<th'+(/Amount|Cost|Profit|GP|Due|Comm/.test(h)&&!h.includes('Status')?' class="numeric"':'')+'>'+h+'</th>').join('')+'</tr></thead><tbody>'+body+'</tbody></table></div><div class="foot"><span>'+ (page==='dashboard'?'Customer overview':'Invoice records')+'</span><span>MASTER · Sales Management</span></div></section>';function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('person').textContent=role==='OWNER'?'· Overview':'· LIM';const visible=role==='OWNER'?customers:customers.filter(c=>c.staff===role);if(page==='dashboard'){$('workspace').innerHTML='<div class="heading"><div><h1>Dashboard</h1><p class="subtitle">Customer balances and account terms</p></div><div class="right">'+(role==='OWNER'?'<select aria-label="Salesperson"><option>All salespeople</option><option>LIM</option><option>TAN</option></select>':'')+'<input id="search" aria-label="Search customers" placeholder="Search customer or country"></div></div>'+table(['Customer','Country','Currency','Term','Current Due','Entry'],visible.map(c=>'<tr data-name="'+c.name+'"><td><b>'+c.name+'</b>'+(role==='OWNER'?'<small>'+c.staff+'</small>':'')+'</td><td>'+c.country+'</td><td>'+c.currency+'</td><td>'+c.term+'</td><td class="numeric amount">'+c.due+'</td><td><button class="entry" data-entry="'+c.id+'">Entry →</button></td></tr>').join(''));$('search').oninput=e=>document.querySelectorAll('tr[data-name]').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(e.target.value.toLowerCase()));}else if(page==='customers'){const c=customers.find(c=>c.id===customer);$('workspace').innerHTML='<div class="heading"><h1>Customers</h1><button class="back" id="back">← Dashboard</button></div><section class="customer"><div class="customer-top"><div><h2>'+c.name+'</h2><p>CUS-DEMO-001 · '+c.country+'</p></div><span class="pill">'+c.due+' due</span></div><div class="customer-grid"><div><p><span class="label">Contact</span>Alex Tan</p><p><span class="label">Email</span>purchasing@example.com</p><p><span class="label">Phone</span>+65 6000 0000</p></div><div><p><span class="label">Currency</span>'+c.currency+'</p><p><span class="label">Term</span>'+c.term+'</p><p><span class="label">Salesperson</span>'+c.staff+'</p></div><div><p><span class="label">Billing</span>18 Example Road</p><p><span class="label"></span>Singapore 000000</p><p><span class="label">Ship to</span>Same as billing address</p></div></div></section>'+table(['Period','Invoice No.','Invoice Amount','Payment Status','Cost MYR','Profit MYR','GP','Transport','Comm Status'],'<tr><td>May 2026</td><td><b>NCT-INV-000001</b><small>18-05-26</small></td><td class="numeric amount">USD 12,000.00</td><td><span class="pill due">USD 5,000.00 due</span></td><td class="numeric">36,000.00</td><td class="numeric amount">12,000.00</td><td class="numeric">25.00%</td><td class="numeric">—</td><td><span class="pill">Pending</span></td></tr><tr><td>April 2026</td><td><b>NCT-INV-000002</b><small>12-04-26</small></td><td class="numeric amount">USD 8,000.00</td><td><span class="pill paid">Fully Paid</span></td><td class="numeric">24,000.00</td><td class="numeric amount">8,000.00</td><td class="numeric">25.00%</td><td class="numeric">—</td><td><span class="pill">Pending</span></td></tr><tr><td>March 2026</td><td><b>NCT-INV-000003</b><small>08-03-26</small></td><td class="numeric amount">USD 10,000.00</td><td><span class="pill paid">Fully Paid</span></td><td class="numeric">30,000.00</td><td class="numeric amount">10,000.00</td><td class="numeric">25.00%</td><td class="numeric">—</td><td><span class="pill paid">Comm. Paid</span></td></tr>')+'<p class="hint">Purchase cost excludes transport. Profit is shown in MYR using the invoice FX rate. Historical sales credit stays with the invoice salesperson.</p>';$('back').onclick=()=>{page='dashboard';render();};}else{$('workspace').innerHTML='<div class="heading"><div><h1>Commission</h1><p class="subtitle">Fully paid transactions · Finance confirms commission separately</p></div><select aria-label="Commission period"><option>All periods</option><option>April 2026</option><option>March 2026</option></select></div>'+table(['Period','Inv','Amount','Cost MYR','Profit MYR','Others Cost','Net Comm'],'<tr><td>April 2026</td><td><b>NCT-INV-000002</b><small>ABC TRADING PTE. LTD.</small></td><td class="numeric amount">USD 8,000.00</td><td class="numeric">24,000.00</td><td class="numeric amount">8,000.00</td><td class="numeric">—</td><td class="numeric">—</td></tr><tr><td>March 2026</td><td><b>NCT-INV-000003</b><small>ABC TRADING PTE. LTD.</small></td><td class="numeric amount">USD 10,000.00</td><td class="numeric">30,000.00</td><td class="numeric amount">10,000.00</td><td class="numeric">—</td><td class="numeric">—</td></tr>','commission')+'<p class="hint">Others Cost and Net Comm remain blank until Finance supplies confirmed values. Fully Paid does not mean Comm. Paid.</p>';}document.querySelectorAll('[data-entry]').forEach(b=>b.onclick=()=>{customer=b.dataset.entry;page='customers';render();});}document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{page=b.dataset.page;render();});$('previewRole').onchange=e=>{role=e.target.value;render();};render();})();